import re,os,json
os.chdir(os.path.dirname(os.path.abspath(__file__)))
SP=os.path.abspath('../../..')   # games-src
rd=lambda p:open(p,encoding='utf-8').read()
h=rd('head.html').replace('/*GXCCSS*/',rd(SP+'/shell/gx-campaign.css'));h=h.replace('</style>',''+rd(SP+'/shell/gx-help.css')+rd(SP+'/shell/gx-tutor.css')+rd(SP+'/shell/gx-skin.css')+rd('skin.css')+'\n:root{--gxh-btn:#b5532f;--gxh-accent:#e0a83a;--gxh-bg:#f6ead2;--gxh-font:var(--ff)}</style>',1);b=rd('body.html')
SRC={'gx-scenario.js':SP+'/shell/gx-scenario.js','scn.js':'scn.js','gx-viewport.js':SP+'/shell/gx-viewport.js','gx-skin.js':SP+'/shell/gx-skin.js','gx-help.js':SP+'/shell/gx-help.js','gx-tutor.js':SP+'/shell/gx-tutor.js','gx-campaign.js':SP+'/shell/gx-campaign.js','perfhud.js':SP+'/perf/perfhud.js','gameaudio.js':SP+'/audio/gameaudio.js','audio-data.js':SP+'/audio/rampart/audio-data.js','gx-glb.js':SP+'/shell/gx-glb.js','gx-glbsprite.js':SP+'/shell/gx-glbsprite.js','three.min.js':SP+'/node_modules/three/build/three.min.js'}
for f in ['gx-scenario.js','scn.js','gx-viewport.js','gx-skin.js','gx-help.js','gx-tutor.js','gx-campaign.js','campaign-data.js','perfhud.js','gameaudio.js','audio-data.js','data.js','geo.js','engine.js','ai.js','icons.js','hlp.js','sound.js','story.js','tutor.js','coach.js','preview.js','bf.js','camp.js','three.min.js','gx-glb.js','gx-glbsprite.js','paint.js','models3d.js','assets.js']:
    tag=f'<script src="{f}"></script>';assert tag in b,f
    if f=='campaign-data.js':src='window.CAMPAIGN = '+json.dumps(json.load(open('../../campaign.json',encoding='utf-8')),separators=(',',':'),ensure_ascii=False)+';'
    elif f=='three.min.js':t=rd(SRC[f]);src='!'+t[t.index('),')+2:]
    else:src=rd(SRC.get(f,f))
    if f=='paint.js':_md=os.path.join(SP,'..','games','rampart-and-vine','media');src='const MEDIA_FILES='+json.dumps(sorted(os.listdir(_md)) if os.path.isdir(_md) else [])+';   // generated by build.py: the pictures in media/\n'+src
    if f=='assets.js':_mo=os.path.join(SP,'..','games','rampart-and-vine','models');src='const MODEL_FILES='+json.dumps(sorted(os.listdir(_mo)) if os.path.isdir(_mo) else [])+';\n'+src
    b=b.replace(tag,'<script>\n'+src.replace('</script','<\\/script')+'\n</script>')
out=h+b
open('../rampart.html','w',encoding='utf-8').write(out)
js='\n'.join(re.findall(r'<script>(.*?)</script>',out,re.S))
open('x.js','w',encoding='utf-8').write(js)
print(len(out))
